css:
.cat-switch{position:relative;display:inline-block;width:38px;height:22px;cursor:pointer}
.cat-switch input{opacity:0;width:0;height:0;position:absolute}
.cat-switch .track{position:absolute;inset:0;border-radius:var(--cat-size-radius-pill);background:rgba(120,120,128,.32);transition:background var(--cat-motion-med) ease;box-shadow:inset 0 0 0 .5px rgba(0,0,0,.04)}
.cat-switch .track::after{content:"";position:absolute;top:2px;left:2px;width:18px;height:18px;border-radius:50%;background:#fff;box-shadow:0 2px 5px rgba(0,0,0,.22),0 0 0 .5px rgba(0,0,0,.04);transition:transform var(--cat-motion-slow) var(--cat-motion-spring)}
.cat-switch input:checked+.track{background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base))}
.cat-switch input:checked+.track::after{transform:translateX(16px)}
.cat-switch input:focus-visible+.track{box-shadow:0 0 0 var(--cat-size-border-focus-ring) var(--cat-semantic-accent-ring)}
.cat-switch input:disabled+.track{opacity:.5;cursor:not-allowed}
